function visionEval(num, den){
  num=+num; den=+den; if(!(num>0&&den>0)) return {error:'分子分母须为正'};
  var decimal=Math.round(num/den*100)/100;
  var logmar=Math.round(Math.log10(den/num)*100)/100;
  var level = decimal>=1?'正常视力':(decimal>=0.5?'轻度下降':(decimal>=0.3?'中度下降':'重度下降'));
  return {num:num, den:den, decimal:decimal, logmar:logmar, level:level};
}
var EXPORTS={visionEval:visionEval};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EyeForgePure = EXPORTS; }
